args.content:
.page {
  min-height: 100vh;
  margin: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background: #0f172a;
  color: #e2e8f0;
  font-family:
    ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica,
    Arial, sans-serif;
}

.card {
  width: min(100%, 440px);
  background: #111827;
  border: 1px solid #1f2937;
  border-radius: 16px;
  padding: 32px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
}

.code {
  margin: 0;
  font-size: 0.875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #f87171;
  font-weight: 700;
}

.title {
  margin: 8px 0 12px;
  font-size: 2rem;
  line-height: 1.2;
}

.message {
  margin: 0 0 24px;
  color: #94a3b8;
  line-height: 1.6;
}

.link {
  display: inline-block;
  color: #0f172a;
  background: #f8fafc;
  text-decoration: none;
  border-radius: 999px;
  padding: 10px 16px;
  font-weight: 600;
}

.link:hover {
  background: #e2e8f0;
}

